import { navigate } from "gatsby";
import React, { useState } from "react";
import type { ReactNode } from "react";
import { useAuth } from "../../auth/AuthContext";
import { AdminRoute } from "../../auth/AdminRoute";

const NAV_ITEMS = [
  { label: "Dashboard", path: "/admin" },
  { label: "Users", path: "/admin/users" },
  { label: "Itineraries", path: "/admin/itineraries" },
  { label: "Support", path: "/admin/support" },
  { label: "Audit log", path: "/admin/audit" },
];

// Maps path segments to readable labels
const PATH_LABELS: Record<string, string> = {
  admin: "Dashboard",
  users: "Users",
  itineraries: "Itineraries",
  support: "Support",
  audit: "Audit log",
  new: "New",
  edit: "Edit",
};

interface Crumb {
  label: string;
  path: string;
}

function buildBreadcrumbs(pathname: string): Crumb[] {
  const segments = pathname.replace(/\/$/, "").split("/").filter(Boolean);
  const crumbs: Crumb[] = [];
  let accumulated = "";

  for (const seg of segments) {
    accumulated += "/" + seg;
    const label = PATH_LABELS[seg] ?? seg.slice(0, 8) + "…";
    crumbs.push({ label, path: accumulated });
  }

  return crumbs;
}

interface Props {
  children: ReactNode;
  title?: string;
  backTo?: string;
  backLabel?: string;
}

export function AdminLayout({ children, title, backTo, backLabel }: Props) {
  return (
    <AdminRoute>
      <AdminShell title={title} backTo={backTo} backLabel={backLabel}>
        {children}
      </AdminShell>
    </AdminRoute>
  );
}

function AdminShell({ children, title, backTo, backLabel }: Props) {
  const { user, signOut } = useAuth();
  const [sidebarOpen, setSidebarOpen] = useState(false);

  async function handleSignOut() {
    await signOut();
    navigate("/login");
  }

  const currentPath =
    typeof window !== "undefined" ? window.location.pathname : "";

  const crumbs = buildBreadcrumbs(currentPath);
  const isNested = crumbs.length > 2;

  // Infer back destination from breadcrumbs if not explicitly provided
  const resolvedBackTo =
    backTo ?? (isNested ? crumbs[crumbs.length - 2].path : null);
  const resolvedBackLabel =
    backLabel ?? (isNested ? crumbs[crumbs.length - 2].label : null);

  return (
    <div className="flex min-h-screen bg-gray-50">
      {/* Sidebar */}
      <aside
        className={`fixed inset-y-0 left-0 z-40 w-56 bg-white shadow-sm transition-transform duration-200 lg:static lg:translate-x-0 ${
          sidebarOpen ? "translate-x-0" : "-translate-x-full"
        }`}
      >
        <div className="flex h-16 items-center border-b border-gray-100 px-5">
          <span className="text-sm font-semibold text-gray-900">Jenny Adventures</span>
        </div>
        <nav className="mt-2 px-3">
          {NAV_ITEMS.map((item) => {
            const active =
              item.path === "/admin"
                ? currentPath === "/admin" || currentPath === "/admin/"
                : currentPath.startsWith(item.path);
            return (
              <button
                key={item.path}
                onClick={() => {
                  navigate(item.path);
                  setSidebarOpen(false);
                }}
                className={`mb-1 w-full rounded-lg px-3 py-2 text-left text-sm transition ${
                  active
                    ? "bg-gray-900 font-medium text-white"
                    : "text-gray-600 hover:bg-gray-100"
                }`}
              >
                {item.label}
              </button>
            );
          })}
        </nav>
        <div className="absolute bottom-0 w-full border-t border-gray-100 p-4">
          <p className="truncate text-xs text-gray-400">{user?.email}</p>
          <button
            onClick={handleSignOut}
            className="mt-2 w-full rounded-lg border border-gray-200 px-3 py-1.5 text-left text-xs text-gray-600 transition hover:bg-gray-100"
          >
            Sign out
          </button>
        </div>
      </aside>

      {/* Overlay for mobile */}
      {sidebarOpen && (
        <div
          className="fixed inset-0 z-30 bg-black/30 lg:hidden"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Main content */}
      <div className="flex flex-1 flex-col overflow-hidden">
        <header className="flex h-16 items-center gap-3 border-b border-gray-100 bg-white px-5">
          {/* Mobile menu button */}
          <button
            onClick={() => setSidebarOpen(true)}
            className="rounded-lg p-1.5 text-gray-500 hover:bg-gray-100 lg:hidden"
            aria-label="Open menu"
          >
            <svg className="h-5 w-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
            </svg>
          </button>

          {/* Back button */}
          {resolvedBackTo && (
            <button
              onClick={() => navigate(resolvedBackTo)}
              className="flex items-center gap-1.5 rounded-lg border border-gray-200 px-3 py-1.5 text-xs font-medium text-gray-600 transition hover:bg-gray-100"
            >
              <svg className="h-3.5 w-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
              </svg>
              {resolvedBackLabel}
            </button>
          )}

          {/* Breadcrumbs */}
          <nav className="hidden items-center gap-1.5 text-xs text-gray-400 sm:flex">
            {crumbs.map((crumb, i) => {
              const isLast = i === crumbs.length - 1;
              return (
                <React.Fragment key={crumb.path}>
                  {i > 0 && <span>/</span>}
                  {isLast ? (
                    <span className="font-medium text-gray-700">{title ?? crumb.label}</span>
                  ) : (
                    <button
                      onClick={() => navigate(crumb.path)}
                      className="hover:text-gray-700 transition"
                    >
                      {crumb.label}
                    </button>
                  )}
                </React.Fragment>
              );
            })}
          </nav>

          {/* Mobile title fallback */}
          {title && (
            <h1 className="text-sm font-semibold text-gray-900 sm:hidden">{title}</h1>
          )}
        </header>

        <main className="flex-1 overflow-auto p-6">{children}</main>
      </div>
    </div>
  );
}
