import { navigate } from "gatsby";
import React, { useEffect, useState } from "react";
import type { ItineraryStatus } from "../types";
import {
  createItinerary,
  getItineraryById,
  updateItinerary,
} from "../../../sessionServices/itineraries/itinerariesService";
import { listUsers } from "../../../sessionServices/users/usersService";
import { writeAuditLog } from "../../../sessionServices/audit/auditLogsService";
import type { UserProfile } from "../types";
import { useAuth } from "../../auth/AuthContext";

interface Props {
  itineraryId?: string;
}

const STATUSES: ItineraryStatus[] = [
  "draft", "in_review", "approved", "shared", "in_follow_up", "closed",
];

const EMPTY_FORM = {
  userId: "",
  title: "",
  summary: "",
  originCity: "",
  destinationCities: "",
  startDate: "",
  endDate: "",
  travelerCount: 1,
  tripType: "",
  budget: "",
  preferences: "",
  internalNotes: "",
  status: "draft" as ItineraryStatus,
};

export function ItineraryForm({ itineraryId }: Props) {
  const { user } = useAuth();
  const isEditing = Boolean(itineraryId);

  const [form, setForm] = useState(EMPTY_FORM);
  const [customers, setCustomers] = useState<UserProfile[]>([]);
  const [loading, setLoading] = useState(isEditing);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    listUsers().then((all) =>
      setCustomers(all.filter((u) => u.role === "customer"))
    );
  }, []);

  useEffect(() => {
    if (!itineraryId) return;
    getItineraryById(itineraryId).then((data) => {
      if (!data) return;
      setForm({
        userId: data.userId,
        title: data.title,
        summary: data.summary,
        originCity: data.originCity ?? "",
        destinationCities: data.destinationCities.join(", "),
        startDate: tsToDateInput(data.startDate),
        endDate: tsToDateInput(data.endDate),
        travelerCount: data.travelerCount,
        tripType: data.tripType ?? "",
        budget: data.budget ? String(data.budget) : "",
        preferences: data.preferences?.join(", ") ?? "",
        internalNotes: data.internalNotes ?? "",
        status: data.status,
      });
      setLoading(false);
    });
  }, [itineraryId]);

  function set(field: keyof typeof EMPTY_FORM, value: string | number) {
    setForm((prev) => ({ ...prev, [field]: value }));
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!user) return;
    setError(null);
    setSaving(true);

    const destinations = form.destinationCities
      .split(",")
      .map((s) => s.trim())
      .filter(Boolean);

    const prefs = form.preferences
      .split(",")
      .map((s) => s.trim())
      .filter(Boolean);

    try {
      if (isEditing && itineraryId) {
        await updateItinerary(itineraryId, {
          title: form.title,
          summary: form.summary,
          status: form.status,
          originCity: form.originCity || undefined,
          destinationCities: destinations,
          startDate: form.startDate,
          endDate: form.endDate,
          travelerCount: Number(form.travelerCount),
          tripType: form.tripType || undefined,
          budget: form.budget ? Number(form.budget) : undefined,
          preferences: prefs,
          internalNotes: form.internalNotes || undefined,
          updatedBy: user.uid,
        });
        await writeAuditLog({
          entityType: "itinerary",
          entityId: itineraryId,
          action: "update",
          after: { title: form.title, status: form.status },
          performedBy: user.uid,
        });
        navigate(`/admin/itineraries/${itineraryId}`);
      } else {
        const id = await createItinerary({
          userId: form.userId,
          title: form.title,
          summary: form.summary,
          originCity: form.originCity || undefined,
          destinationCities: destinations,
          startDate: form.startDate,
          endDate: form.endDate,
          travelerCount: Number(form.travelerCount),
          tripType: form.tripType || undefined,
          budget: form.budget ? Number(form.budget) : undefined,
          preferences: prefs,
          internalNotes: form.internalNotes || undefined,
          createdBy: user.uid,
        });
        await writeAuditLog({
          entityType: "itinerary",
          entityId: id,
          action: "create",
          after: { title: form.title, userId: form.userId },
          performedBy: user.uid,
        });
        navigate(`/admin/itineraries/${id}`);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An error occurred.");
    } finally {
      setSaving(false);
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center py-16">
        <div className="h-6 w-6 animate-spin rounded-full border-4 border-gray-300 border-t-gray-800" />
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} className="max-w-2xl space-y-5">
      <div className="grid gap-5 sm:grid-cols-2">
        <Field label="Customer" required className="sm:col-span-2">
          <select
            required
            value={form.userId}
            onChange={(e) => set("userId", e.target.value)}
            className={inputClass}
            disabled={isEditing}
          >
            <option value="">Select a customer…</option>
            {customers.map((c) => (
              <option key={c.uid} value={c.uid}>
                {c.fullName} ({c.email})
              </option>
            ))}
          </select>
        </Field>

        <Field label="Title" required className="sm:col-span-2">
          <input
            type="text"
            required
            value={form.title}
            onChange={(e) => set("title", e.target.value)}
            className={inputClass}
          />
        </Field>

        <Field label="Summary" required className="sm:col-span-2">
          <textarea
            required
            rows={3}
            value={form.summary}
            onChange={(e) => set("summary", e.target.value)}
            className={inputClass}
          />
        </Field>

        <Field label="Origin city">
          <input
            type="text"
            value={form.originCity}
            onChange={(e) => set("originCity", e.target.value)}
            className={inputClass}
          />
        </Field>

        <Field label="Destination cities" hint="Comma-separated">
          <input
            type="text"
            placeholder="Paris, Rome, Barcelona"
            value={form.destinationCities}
            onChange={(e) => set("destinationCities", e.target.value)}
            className={inputClass}
          />
        </Field>

        <Field label="Start date" required>
          <input
            type="date"
            required
            value={form.startDate}
            onChange={(e) => set("startDate", e.target.value)}
            className={inputClass}
          />
        </Field>

        <Field label="End date" required>
          <input
            type="date"
            required
            value={form.endDate}
            onChange={(e) => set("endDate", e.target.value)}
            className={inputClass}
          />
        </Field>

        <Field label="Travelers" required>
          <input
            type="number"
            required
            min={1}
            value={form.travelerCount}
            onChange={(e) => set("travelerCount", e.target.value)}
            className={inputClass}
          />
        </Field>

        <Field label="Trip type">
          <input
            type="text"
            placeholder="e.g. honeymoon, family, adventure"
            value={form.tripType}
            onChange={(e) => set("tripType", e.target.value)}
            className={inputClass}
          />
        </Field>

        <Field label="Budget (CAD)">
          <input
            type="number"
            min={0}
            value={form.budget}
            onChange={(e) => set("budget", e.target.value)}
            className={inputClass}
          />
        </Field>

        <Field label="Preferences" hint="Comma-separated">
          <input
            type="text"
            placeholder="culture, gastronomy, adventure"
            value={form.preferences}
            onChange={(e) => set("preferences", e.target.value)}
            className={inputClass}
          />
        </Field>

        {isEditing && (
          <Field label="Status">
            <select
              value={form.status}
              onChange={(e) => set("status", e.target.value as ItineraryStatus)}
              className={inputClass}
            >
              {STATUSES.map((s) => (
                <option key={s} value={s}>{s.replace("_", " ")}</option>
              ))}
            </select>
          </Field>
        )}

        <Field label="Internal notes" className="sm:col-span-2">
          <textarea
            rows={3}
            value={form.internalNotes}
            onChange={(e) => set("internalNotes", e.target.value)}
            className={inputClass}
          />
        </Field>
      </div>

      {error && (
        <p className="rounded-lg bg-red-50 px-3 py-2 text-sm text-red-600">{error}</p>
      )}

      <div className="flex gap-3 pt-2">
        <button
          type="submit"
          disabled={saving}
          className="rounded-lg bg-gray-900 px-5 py-2 text-sm font-medium text-white transition hover:bg-gray-700 disabled:opacity-60"
        >
          {saving ? "Saving..." : isEditing ? "Save changes" : "Create itinerary"}
        </button>
        <button
          type="button"
          onClick={() => navigate("/admin/itineraries")}
          className="rounded-lg border border-gray-300 px-5 py-2 text-sm font-medium text-gray-700 transition hover:bg-gray-100"
        >
          Cancel
        </button>
      </div>
    </form>
  );
}

function Field({
  label,
  required,
  hint,
  className,
  children,
}: {
  label: string;
  required?: boolean;
  hint?: string;
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <div className={className}>
      <label className="mb-1 block text-sm font-medium text-gray-700">
        {label}
        {required && <span className="ml-0.5 text-red-500">*</span>}
        {hint && <span className="ml-1 font-normal text-gray-400">({hint})</span>}
      </label>
      {children}
    </div>
  );
}

function tsToDateInput(ts: unknown): string {
  try {
    const date = (ts as { toDate: () => Date }).toDate();
    return date.toISOString().slice(0, 10);
  } catch {
    return "";
  }
}

const inputClass =
  "block w-full rounded-lg border border-gray-300 px-3 py-2 text-sm text-gray-900 focus:border-gray-800 focus:outline-none focus:ring-1 focus:ring-gray-800";
